import {StructuredNoteContentAdapter,createStructuredNoteContentDocument,structuredNoteContentAdapterPublicationCount,isCanonicalStructuredNoteContentAdapter} from './adapters/structured-note-content.js';
import {NoteBindingAdapter} from './foundation/notes/note-binding.js';
import {libraryNoteBindingInput} from './adapters/note-binding-domains.js';
import {StickyNoteWindowOwner} from './foundation/notes/sticky-note-window.js';

const assert=(condition,message)=>{if(!condition)throw Error(message)};
const stable=value=>JSON.stringify(value);
const run=(id,fn)=>{try{return {id,status:'PASS',evidence:fn()}}catch(error){return {id,status:'FAIL',error:String(error?.stack||error)}}};
const rejects=(fn,token)=>{try{fn()}catch(error){const message=String(error?.message||error);assert(message.includes(token),`expected ${token}, got ${message}`);return message}throw Error(`expected rejection ${token}`)};
const available=kind=>({state:'available',evidence:{kind}});

function bind(owner,noteId){
  owner.bind(noteId,libraryNoteBindingInput({noteId,documentId:`source-${noteId}`,blockId:`source-block-${noteId}`,route:`PERSONAL:CEP/W06/correction/${noteId}`,availability:available('W6C_CORRECTION')}));
}
function documentFor(noteId,documentId=`structured-note-content::${encodeURIComponent(noteId)}`){
  return createStructuredNoteContentDocument(noteId,{documentId,title:`ملاحظة ${noteId}`,blocks:[{id:`${noteId}-p1`,type:'paragraph',html:`content:${noteId}`}]});
}
function graph({bridge}={}){return {bindingOwner:new NoteBindingAdapter(),windowOwner:new StickyNoteWindowOwner({hostGraph:{},capabilityBridge:bridge})}}
function prepare(g,noteId){bind(g.bindingOwner,noteId);g.windowOwner.register(noteId,{geometry:{x:40,y:50,width:360,height:280},open:true,pinned:false})}
function make(g,noteId,documentId){return new StructuredNoteContentAdapter({noteId,document:documentFor(noteId,documentId),bindingOwner:g.bindingOwner,windowOwner:g.windowOwner,mode:'edit'})}

export function runW6CStructuredNoteContentCorrectionProof(){
  const cases=[];
  cases.push(run('01.first-publication-succeeds',()=>{const g=graph(),id='corr-first';prepare(g,id);const before=structuredNoteContentAdapterPublicationCount(),a=make(g,id);assert(isCanonicalStructuredNoteContentAdapter(a),'first adapter not canonical');assert(structuredNoteContentAdapterPublicationCount()===before+1,'publication count did not increment exactly once');return {documentId:a.documentId,countDelta:1}}));
  cases.push(run('02.same-note-same-graph-duplicate-rejected-before-publication',()=>{const g=graph(),id='corr-duplicate';prepare(g,id);const a=make(g,id),beforeCount=structuredNoteContentAdapterPublicationCount(),beforeDoc=stable(a.snapshot()),beforeHost=a.surfaceHost,beforeAdapter=a.documentAdapter;const message=rejects(()=>make(g,id),'DUPLICATE_STRUCTURED_NOTE_CONTENT_ADAPTER');assert(structuredNoteContentAdapterPublicationCount()===beforeCount,'duplicate increased publication count');assert(stable(a.snapshot())===beforeDoc&&a.surfaceHost===beforeHost&&a.documentAdapter===beforeAdapter,'duplicate attempt changed canonical adapter');return {message,publicationCountUnchanged:true,canonicalHostStable:true}}));
  cases.push(run('03.original-adapter-usable-after-duplicate-rejection',()=>{const g=graph(),id='corr-duplicate-usable';prepare(g,id);const a=make(g,id);rejects(()=>make(g,id),'DUPLICATE_STRUCTURED_NOTE_CONTENT_ADAPTER');const before=a.transactionDescriptor().historyLength;a.surfaceHost.updateContent(`${id}-p1`,{html:'after duplicate rejection'});assert(a.snapshot().blocks[0].html==='after duplicate rejection','canonical adapter unusable after duplicate rejection');assert(a.transactionDescriptor().historyLength===before+1,'history owner unusable after duplicate rejection');return {historyAdvanced:true,documentId:a.documentId}}));
  cases.push(run('04.hide-reopen-reuses-first-canonical-adapter',()=>{const g=graph(),id='corr-reopen';prepare(g,id);const a=make(g,id),doc=a.documentId,host=a.surfaceHost,adapter=a.documentAdapter,binding=stable(a.bindingDescriptor());g.windowOwner.hide(id);g.windowOwner.open(id);assert(a.documentId===doc&&a.surfaceHost===host&&a.documentAdapter===adapter&&stable(a.bindingDescriptor())===binding,'reopen drifted canonical adapter');rejects(()=>make(g,id),'DUPLICATE_STRUCTURED_NOTE_CONTENT_ADAPTER');return {documentId:doc,sameHost:true,sameDocumentAdapter:true}}));
  cases.push(run('05.separate-window-projection-reuses-first-canonical-adapter',()=>{const bridge={id:'corr-bridge',capabilities:()=>({alwaysOnTop:false,separateWindow:true}),requestSeparateWindow:()=>({ok:true,active:true})},g=graph({bridge}),id='corr-separate';prepare(g,id);const a=make(g,id),doc=a.documentId,host=a.surfaceHost,adapter=a.documentAdapter,binding=stable(a.bindingDescriptor()),request=g.windowOwner.requestSeparateWindow(id),projection=a.presentationBinding({windowInstanceId:'corr-native-window'});assert(request.ok&&projection.presentation.hostKind==='separate-window','separate-window projection failed');assert(a.documentId===doc&&a.surfaceHost===host&&a.documentAdapter===adapter&&stable(a.bindingDescriptor())===binding,'separate-window created/replaced canonical engine');rejects(()=>make(g,id),'DUPLICATE_STRUCTURED_NOTE_CONTENT_ADAPTER');return {sameHost:true,sameDocumentAdapter:true,sameBinding:true,documentId:doc}}));
  cases.push(run('06.two-distinct-notes-distinct-document-ids-succeed',()=>{const g=graph(),aId='corr-A',bId='corr-B';prepare(g,aId);prepare(g,bId);const a=make(g,aId,'corr-doc-A'),b=make(g,bId,'corr-doc-B');assert(a.documentId!==b.documentId&&a.noteId!==b.noteId&&a.documentAdapter!==b.documentAdapter,'valid notes not isolated');return {documents:[a.documentId,b.documentId]}}));
  cases.push(run('07.document-id-collision-rejects-second-publication',()=>{const g=graph(),aId='corr-collision-A',bId='corr-collision-B',doc='corr-SAME-DOCUMENT';prepare(g,aId);prepare(g,bId);const a=make(g,aId,doc),beforeCount=structuredNoteContentAdapterPublicationCount(),before=stable(a.snapshot());const message=rejects(()=>make(g,bId,doc),'STRUCTURED_NOTE_CONTENT_DOCUMENT_ID_COLLISION');assert(structuredNoteContentAdapterPublicationCount()===beforeCount,'collision increased publication count');assert(stable(a.snapshot())===before,'collision changed first adapter');return {message,publicationCountUnchanged:true,firstDocumentId:a.documentId}}));
  cases.push(run('08.collision-rejection-does-not-reserve-note-slot',()=>{const g=graph(),aId='corr-retry-A',bId='corr-retry-B';prepare(g,aId);prepare(g,bId);make(g,aId,'corr-retry-shared');const beforeCount=structuredNoteContentAdapterPublicationCount();rejects(()=>make(g,bId,'corr-retry-shared'),'STRUCTURED_NOTE_CONTENT_DOCUMENT_ID_COLLISION');assert(structuredNoteContentAdapterPublicationCount()===beforeCount,'failed collision published phantom');const b=make(g,bId,'corr-retry-B-legal');assert(b.documentId==='corr-retry-B-legal'&&isCanonicalStructuredNoteContentAdapter(b),'legal retry after collision failed');return {retryDocumentId:b.documentId,countDeltaAfterRetry:1}}));
  cases.push(run('09.malformed-failure-does-not-reserve-publication-slot',()=>{const g=graph(),id='corr-malformed-retry';prepare(g,id);const before=structuredNoteContentAdapterPublicationCount(),bad=documentFor(id);bad.id=' bad ';rejects(()=>new StructuredNoteContentAdapter({noteId:id,document:bad,bindingOwner:g.bindingOwner,windowOwner:g.windowOwner}),'MALFORMED_STRUCTURED_NOTE_CONTENT_IDENTITY');assert(structuredNoteContentAdapterPublicationCount()===before,'malformed attempt published phantom');const valid=make(g,id,'corr-malformed-valid');assert(valid.documentId==='corr-malformed-valid','valid retry after malformed failure did not succeed');return {validRetry:true}}));
  cases.push(run('10.independent-canonical-graphs-may-reuse-textual-identities',()=>{const id='corr-independent-same-note',doc='corr-independent-same-document',g1=graph(),g2=graph();prepare(g1,id);prepare(g2,id);const a=make(g1,id,doc),b=make(g2,id,doc);assert(a!==b&&a.bindingOwner!==b.bindingOwner&&a.windowOwner!==b.windowOwner&&a.documentId===b.documentId,'independent graph identity was incorrectly globalized');return {sameTextualNoteId:true,sameTextualDocumentId:true,independentGraphs:true}}));
  cases.push(run('11.document-collision-does-not-affect-first-adapter-state',()=>{const g=graph(),aId='corr-state-A',bId='corr-state-B';prepare(g,aId);prepare(g,bId);const a=make(g,aId,'corr-state-shared');a.surfaceHost.routePointerSelection(`${aId}-p1`);const before={doc:stable(a.snapshot()),tx:stable(a.transactionDescriptor()),selection:stable(a.documentAdapter.selectedFragmentIdentity()),window:stable(g.windowOwner.window(aId)),binding:stable(a.bindingDescriptor())};rejects(()=>make(g,bId,'corr-state-shared'),'STRUCTURED_NOTE_CONTENT_DOCUMENT_ID_COLLISION');assert(stable(a.snapshot())===before.doc&&stable(a.transactionDescriptor())===before.tx&&stable(a.documentAdapter.selectedFragmentIdentity())===before.selection&&stable(g.windowOwner.window(aId))===before.window&&stable(a.bindingDescriptor())===before.binding,'collision leaked into first note state');return {firstAdapterUnchanged:true}}));
  cases.push(run('12.canonical-publication-remains-self-consistent',()=>{const g=graph(),id='corr-self-consistent';prepare(g,id);const a=make(g,id);assert(a.assertCanonicalComposition()===true,'canonical composition check failed after publication');return {canonical:true,documentId:a.documentId}}));
  const failed=cases.filter(x=>x.status!=='PASS');
  return {schemaVersion:1,kind:'W6_C_STRUCTURED_NOTE_CONTENT_ADAPTER_BOUNDED_CORRECTION_PROOF',classification:'W6_C_CORRECTION_EXECUTION_EVIDENCE_NOT_CONTROLLER_ACCEPTANCE',status:failed.length?'FAIL':'PASS',caseCount:cases.length,passCount:cases.length-failed.length,failCount:failed.length,cases};
}
